const storage = {
  get<T>(key: string, fallback: T): T {
    try { const raw = localStorage.getItem(key); return raw ? JSON.parse(raw) as T : fallback; } catch { return fallback; }
  },
  set<T>(key: string, value: T) { localStorage.setItem(key, JSON.stringify(value)); },
};

function usePersistent<T>(key: string, fallback: T) {
  const [value, setValue] = useState<T>(() => storage.get(key, fallback));
  useEffect(() => storage.set(key, value), [key, value]);
  return [value, setValue] as const;
}

