function StatCard({ label, value, change, icon: Icon, accent = false }: { label: string; value: string; change: string; icon: typeof Activity; accent?: boolean }) {
  return <div className={`panel stat-card panel-hover reveal ${accent ? 'kpi-accent' : ''}`}><div className="flex items-center justify-between"><span className="eyebrow">{label}</span><Icon size={17} className="text-[hsl(var(--primary))]" /></div><div className="stat-value">{value}</div><div className="stat-change flex items-center gap-1">{change.startsWith('-') ? <ArrowDownRight size={13} /> : <ArrowUpRight size={13} />}{change}</div></div>;
}

function SparkChart({ values, color = 'hsl(166 74% 35%)', fill = true }: { values: number[]; color?: string; fill?: boolean }) {
  const max = Math.max(...values), min = Math.min(...values); const points = values.map((v, i) => `${(i / (values.length - 1)) * 100},${92 - ((v - min) / Math.max(max - min, 1)) * 78}`).join(' ');
  return <svg className="sparkline" viewBox="0 0 100 100" preserveAspectRatio="none" aria-label="Performance trend"><defs><linearGradient id="chartFill" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stopColor={color} stopOpacity=".2" /><stop offset="1" stopColor={color} stopOpacity="0" /></linearGradient></defs>{fill && <polygon points={`0,100 ${points} 100,100`} fill="url(#chartFill)" />}{[20, 50, 80].map(y => <line key={y} x1="0" x2="100" y1={y} y2={y} stroke="currentColor" strokeOpacity=".08" strokeWidth=".6" />)}<polyline points={points} fill="none" stroke={color} strokeWidth="2.3" vectorEffect="non-scaling-stroke" strokeLinecap="round" strokeLinejoin="round" /></svg>;
}

function StatusBadge({ status }: { status: Status }) { return <span className={`badge ${status === 'Active' ? 'badge-active' : status === 'Planned' ? 'badge-planned' : status === 'Completed' ? 'badge-complete' : 'badge-paused'}`}><span className="w-1.5 h-1.5 rounded-full bg-current" />{status}</span>; }

