function Campaigns({ campaigns, setCampaigns, notify }: { campaigns: Campaign[]; setCampaigns: (c: Campaign[]) => void; notify: (s: string) => void }) {
  const [query, setQuery] = useState(''); const [status, setStatus] = useState<'All' | Status>('All');
  const filtered = useMemo(() => campaigns.filter(c => (status === 'All' || c.status === status) && `${c.name} ${c.objective} ${c.audience}`.toLowerCase().includes(query.toLowerCase())), [campaigns, query, status]);
  const remove = (id: string) => { if (window.confirm('Delete this campaign? This action cannot be undone.')) { setCampaigns(campaigns.filter(c => c.id !== id)); notify('Campaign deleted'); } };
  return <div className="mp-content"><PageHeader eyebrow="Workspace / campaigns" title="Campaigns" copy="A complete view of every motion in market, from first brief to final readout." actions={<Link href="/campaigns/new" className="btn btn-primary" data-testid="button-create-campaign"><Plus size={16} /> New campaign</Link>} />
    <div className="panel p-3 mb-4 flex flex-wrap gap-2 items-center"><div className="relative flex-1 min-w-[220px]"><Search size={15} className="absolute left-3 top-3 subtle" /><input className="search-input pl-9" placeholder="Search campaigns, audiences, objectives..." value={query} onChange={e => setQuery(e.target.value)} data-testid="input-search-campaigns" /></div><div className="flex items-center gap-2"><Filter size={15} className="subtle" /><select className="form-select w-auto min-w-[135px]" value={status} onChange={e => setStatus(e.target.value as 'All' | Status)} data-testid="select-campaign-status"><option>All</option><option>Active</option><option>Planned</option><option>Completed</option><option>Paused</option></select></div></div>
    <section className="panel table-wrap reveal"><table><thead><tr><th>Campaign</th><th>Audience</th><th>Channels</th><th>Dates</th><th>Budget</th><th>Status</th><th>Health</th><th></th></tr></thead><tbody>{filtered.length ? filtered.map(c => <tr key={c.id} data-testid={`row-campaign-${c.id}`}><td><Link href={`/campaigns/${c.id}`} className="font-semibold hover:text-[hsl(var(--primary))]" data-testid={`link-view-campaign-${c.id}`}>{c.name}</Link><div className="text-[11px] subtle mt-1">{c.objective}</div></td><td>{c.audience}</td><td><div className="flex gap-1 flex-wrap max-w-[155px]">{c.platforms.map(p => <span key={p} className="badge bg-[hsl(var(--muted))]">{p}</span>)}</div></td><td className="font-mono text-[11px]">{dateShort(c.startDate)} — {dateShort(c.endDate)}</td><td className="font-mono">{money(c.budget)}</td><td><StatusBadge status={c.status} /></td><td><div className="flex items-center gap-2"><div className="w-16 progress-track"><div className="progress-fill" style={{ width: `${c.healthScore}%` }} /></div><span className="text-xs font-mono">{c.healthScore}</span></div></td><td><div className="flex gap-1"><Link href={`/campaigns/${c.id}`} className="btn btn-ghost p-2" aria-label="View campaign" data-testid={`button-view-${c.id}`}><Eye size={15} /></Link><Link href={`/campaigns/${c.id}?edit=true`} className="btn btn-ghost p-2" aria-label="Edit campaign" data-testid={`button-edit-${c.id}`}><Pencil size={14} /></Link><button className="btn btn-ghost p-2 hover:text-[hsl(var(--destructive))]" onClick={() => remove(c.id)} aria-label="Delete campaign" data-testid={`button-delete-${c.id}`}><Trash2 size={14} /></button></div></td></tr>) : <tr><td colSpan={8}><EmptyState title="No campaigns match" copy="Try a different search or reset your filters." action={<button className="btn btn-soft" onClick={() => { setQuery(''); setStatus('All'); }} data-testid="button-reset-filters">Reset filters</button>} /></td></tr>}</tbody></table></section>
  </div>;
}

function EmptyState({ title, copy, action }: { title: string; copy: string; action?: ReactNode }) { return <div className="text-center py-16 px-6"><div className="mx-auto w-11 h-11 rounded-xl bg-[hsl(var(--muted))] grid place-items-center mb-4"><ListFilter size={19} className="subtle" /></div><div className="font-semibold">{title}</div><p className="subtle text-sm mt-1 mb-4">{copy}</p>{action}</div>; }

function CampaignForm({ initial, onSave, onCancel, notify }: { initial?: Campaign; onSave: (c: Campaign) => void; onCancel: () => void; notify: (s: string) => void }) {
  const [form, setForm] = useState<Campaign>(initial ?? { id: `cmp-${Date.now()}`, name: '', objective: 'Pipeline generation', audience: '', platforms: ['LinkedIn'], startDate: '2025-03-20', endDate: '2025-04-30', budget: 20000, status: 'Planned', metrics: { reach: 0, impressions: 0, clicks: 0, conversions: 0, ctr: 0, roas: 0 }, healthScore: 78 });
  const [error, setError] = useState('');
  const update = (key: keyof Campaign, value: string | number) => setForm(f => ({ ...f, [key]: value }));
  const save = (e: React.FormEvent) => { e.preventDefault(); if (!form.name.trim() || !form.audience.trim()) { setError('Campaign name and audience are required.'); return; } if (form.budget <= 0) { setError('Budget must be greater than zero.'); return; } if (new Date(form.endDate) < new Date(form.startDate)) { setError('End date must be after start date.'); return; } onSave(form); notify(initial ? 'Campaign updated' : 'Campaign created'); };
  return <div className="mp-content"><PageHeader eyebrow={initial ? 'Campaign / edit' : 'Campaign / new'} title={initial ? 'Edit campaign' : 'Build a campaign'} copy="Give the team a clear brief. You can fill in performance data as the campaign moves." actions={<button className="btn btn-soft" onClick={onCancel} data-testid="button-cancel-campaign">Cancel</button>} /><form className="panel p-6 max-w-4xl reveal" onSubmit={save}><div className="form-grid"><div className="field-full"><label className="form-label">Campaign name</label><input className="form-input" value={form.name} onChange={e => update('name', e.target.value)} placeholder="e.g. Spring Signal" data-testid="input-campaign-name" /><div className="form-hint">Use a name the whole team will recognize in a weekly review.</div></div><div><label className="form-label">Primary objective</label><select className="form-select" value={form.objective} onChange={e => update('objective', e.target.value)} data-testid="select-campaign-objective">{['Pipeline generation', 'Brand awareness', 'Customer retention', 'Product education', 'Demand capture', 'Account engagement'].map(v => <option key={v}>{v}</option>)}</select></div><div><label className="form-label">Audience</label><input className="form-input" value={form.audience} onChange={e => update('audience', e.target.value)} placeholder="e.g. Growth leaders" data-testid="input-campaign-audience" /></div><div><label className="form-label">Start date</label><input type="date" className="form-input" value={form.startDate} onChange={e => update('startDate', e.target.value)} data-testid="input-campaign-start" /></div><div><label className="form-label">End date</label><input type="date" className="form-input" value={form.endDate} onChange={e => update('endDate', e.target.value)} data-testid="input-campaign-end" /></div><div><label className="form-label">Planned budget</label><input type="number" className="form-input" value={form.budget} onChange={e => update('budget', Number(e.target.value))} data-testid="input-campaign-budget" /></div><div><label className="form-label">Workflow status</label><select className="form-select" value={form.status} onChange={e => update('status', e.target.value)} data-testid="select-campaign-workflow">{(['Planned', 'Active', 'Paused', 'Completed'] as Status[]).map(v => <option key={v}>{v}</option>)}</select></div><div className="field-full"><label className="form-label">Channels</label><div className="flex flex-wrap gap-2">{['LinkedIn', 'Google', 'Instagram', 'YouTube', 'Email'].map(p => <label key={p} className={`badge cursor-pointer ${form.platforms.includes(p) ? 'badge-active' : 'bg-[hsl(var(--muted))]'}`}><input type="checkbox" className="sr-only" checked={form.platforms.includes(p)} onChange={e => setForm(f => ({ ...f, platforms: e.target.checked ? [...f.platforms, p] : f.platforms.filter(x => x !== p) }))} />{form.platforms.includes(p) && <Check size={11} />}{p}</label>)}</div></div></div>{error && <div className="form-error mt-5">{error}</div>}<div className="border-t border-[hsl(var(--border))] mt-7 pt-5 flex justify-end gap-2"><button type="button" className="btn btn-soft" onClick={onCancel} data-testid="button-cancel-form">Discard</button><button type="submit" className="btn btn-primary" data-testid="button-save-campaign"><Check size={15} /> {initial ? 'Save changes' : 'Create campaign'}</button></div></form></div>;
}

function CampaignDetail({ campaigns, setCampaigns, notify }: { campaigns: Campaign[]; setCampaigns: (c: Campaign[]) => void; notify: (s: string) => void }) {
  const [, params] = useRoute('/campaigns/:id'); const [, setLocation] = useLocation(); const campaign = campaigns.find(c => c.id === params?.id); const [editing, setEditing] = useState(() => window.location.search.includes('edit=true'));
  if (!campaign) return <div className="mp-content"><EmptyState title="Campaign not found" copy="This campaign may have been deleted or moved." action={<Link className="btn btn-primary" href="/campaigns" data-testid="link-back-campaigns">Back to campaigns</Link>} /></div>;
  if (editing) return <CampaignForm initial={campaign} onCancel={() => setEditing(false)} notify={notify} onSave={c => { setCampaigns(campaigns.map(x => x.id === c.id ? c : x)); setEditing(false); }} />;
  const max = Math.max(campaign.metrics.reach, 1);
  return <div className="mp-content"><PageHeader eyebrow={`Campaign / ${campaign.name}`} title={campaign.name} copy={`${campaign.objective} · ${campaign.audience}`} actions={<><button className="btn btn-soft" onClick={() => setEditing(true)} data-testid="button-edit-detail"><Pencil size={15} /> Edit</button><button className="btn btn-primary" onClick={() => notify('Report queued for download')} data-testid="button-download-campaign"><Download size={15} /> Export</button></>} /><div className="flex flex-wrap gap-2 mb-5"><StatusBadge status={campaign.status} /><span className="badge bg-[hsl(var(--muted))]">{dateShort(campaign.startDate)} — {dateShort(campaign.endDate)}</span>{campaign.platforms.map(p => <span className="badge bg-[hsl(var(--muted))]" key={p}>{p}</span>)}</div><div className="stat-grid mb-5"><StatCard label="Reach" value={compact(campaign.metrics.reach)} change="+12.8%" icon={Users} /><StatCard label="Impressions" value={compact(campaign.metrics.impressions)} change="+9.4%" icon={Eye} /><StatCard label="Conversions" value={compact(campaign.metrics.conversions)} change="+18.1%" icon={TrendingUp} accent /><StatCard label="Return on ad spend" value={`${campaign.metrics.roas.toFixed(2)}×`} change="+0.38×" icon={CircleGauge} /></div><div className="grid-2"><section className="panel chart-box"><div className="section-head"><div><div className="section-title">Performance arc</div><div className="subtle text-xs mt-1">Daily conversion velocity</div></div><span className="eyebrow">{money(campaign.budget)} budget</span></div><SparkChart values={[24, 31, 28, 44, 39, 53, 58, 56, 71, 64, 76, 82, 80, 91, 88]} /><div className="grid grid-cols-3 gap-3 mt-5"><div><div className="eyebrow">CTR</div><div className="font-semibold mt-1">{campaign.metrics.ctr.toFixed(2)}%</div></div><div><div className="eyebrow">CPC</div><div className="font-semibold mt-1">$4.12</div></div><div><div className="eyebrow">CAC</div><div className="font-semibold mt-1">$86.40</div></div></div></section><section className="panel p-5"><div className="section-head"><div><div className="section-title">Health score</div><div className="subtle text-xs mt-1">Based on 7 live signals</div></div><ShieldCheck className="text-[hsl(var(--primary))]" size={20} /></div><div className="text-5xl font-semibold tracking-[-.08em] mt-5">{campaign.healthScore}<span className="text-lg subtle tracking-normal"> / 100</span></div><div className="progress-track mt-4"><div className="progress-fill" style={{ width: `${campaign.healthScore}%` }} /></div><div className="space-y-3 mt-6">{[['Delivery pacing', 92], ['Conversion velocity', 86], ['Audience fit', 89]].map(([label, value]) => <div key={label as string}><div className="flex justify-between text-xs mb-1.5"><span>{label}</span><span className="font-mono subtle">{value}</span></div><div className="progress-track"><div className="progress-fill" style={{ width: `${value}%` }} /></div></div>)}</div></section></div><section className="panel p-5 mt-5"><div className="section-head"><div><div className="section-title">Channel contribution</div><div className="subtle text-xs mt-1">Reach and conversion share by platform</div></div></div>{campaign.platforms.map((p, i) => <div key={p} className="grid grid-cols-[100px_1fr_80px] items-center gap-4 mb-4 last:mb-0"><span className="text-sm font-medium">{p}</span><div className="progress-track h-2"><div className="progress-fill" style={{ width: `${78 - i * 19}%`, background: i === 0 ? 'hsl(var(--primary))' : 'hsl(var(--accent))' }} /></div><span className="text-right font-mono text-xs">{Math.max(19, 78 - i * 19)}%</span></div>)}</section></div>;
}

function Analytics({ campaigns }: { campaigns: Campaign[] }) {
  const totals = campaigns.reduce((a, c) => ({ reach: a.reach + c.metrics.reach, clicks: a.clicks + c.metrics.clicks, conversions: a.conversions + c.metrics.conversions }), { reach: 0, clicks: 0, conversions: 0 });
  return <div className="mp-content"><PageHeader eyebrow="Workspace / analytics" title="Analytics" copy="The shape of performance across campaigns and channels." actions={<button className="btn btn-soft" onClick={() => window.print()} data-testid="button-print-analytics"><Printer size={15} /> Print view</button>} /><div className="stat-grid mb-5"><StatCard label="Reach" value={compact(totals.reach)} change="+18.6%" icon={Users} /><StatCard label="Clicks" value={compact(totals.clicks)} change="+11.2%" icon={MousePointerClick} /><StatCard label="Conversions" value={compact(totals.conversions)} change="+14.2%" icon={TrendingUp} accent /><StatCard label="Avg. engagement" value="4.86%" change="+0.7%" icon={Heart} /></div><div className="grid-2 mb-5"><section className="panel chart-box"><div className="section-head"><div><div className="section-title">Conversion trend</div><div className="subtle text-xs mt-1">Rolling 12-week view</div></div><div className="flex gap-3 text-[10px] font-mono subtle"><span><i className="inline-block w-2 h-2 rounded-full bg-[hsl(var(--primary))] mr-1" />Conversions</span><span><i className="inline-block w-2 h-2 rounded-full bg-[hsl(var(--accent))] mr-1" />Target</span></div></div><SparkChart values={[55, 61, 58, 72, 68, 79, 76, 88, 85, 96, 103, 111, 107, 124]} /></section><section className="panel p-5"><div className="section-title mb-4">Attribution mix</div>{[['Paid social', 38, 'hsl(var(--primary))'], ['Organic search', 27, 'hsl(var(--accent))'], ['Email', 21, 'hsl(215 68% 55%)'], ['Direct & referral', 14, 'hsl(262 60% 61%)']].map(([label, pct, color]) => <div key={label as string} className="mb-4"><div className="flex justify-between text-xs mb-2"><span>{label}</span><span className="font-mono">{pct}%</span></div><div className="progress-track"><div className="progress-fill" style={{ width: `${pct}%`, background: color as string }} /></div></div>)}</section></div><section className="panel table-wrap"><div className="p-5 pb-1 section-title">Campaign comparison</div><table><thead><tr><th>Campaign</th><th>Reach</th><th>CTR</th><th>Conversions</th><th>ROAS</th><th>Trend</th></tr></thead><tbody>{campaigns.map(c => <tr key={c.id}><td className="font-semibold">{c.name}</td><td className="font-mono">{compact(c.metrics.reach)}</td><td className="font-mono">{c.metrics.ctr.toFixed(2)}%</td><td className="font-mono">{compact(c.metrics.conversions)}</td><td className="font-mono">{c.metrics.roas.toFixed(2)}×</td><td><span className="stat-change flex items-center gap-1"><ArrowUpRight size={13} />{c.status === 'Planned' ? 'Forecast' : 'On track'}</span></td></tr>)}</tbody></table></section></div>;
}

function Audience({ segments }: { segments: Segment[] }) {
  return <div className="mp-content"><PageHeader eyebrow="Workspace / audience" title="Audience intelligence" copy="Know who is leaning in, where they are, and what to say next." actions={<button className="btn btn-primary" onClick={() => alert('Audience export prepared')} data-testid="button-export-audience"><Download size={15} /> Export segments</button>} /><div className="grid-3 mb-5"><div className="panel p-5 kpi-accent"><div className="eyebrow">Known audience</div><div className="stat-value">34,770</div><div className="subtle text-xs">+8.4% from last month</div></div><div className="panel p-5"><div className="eyebrow">Returning visitors</div><div className="stat-value">42.8%</div><div className="subtle text-xs">Strongest in Strategic Shapers</div></div><div className="panel p-5"><div className="eyebrow">Top device</div><div className="stat-value">Desktop</div><div className="subtle text-xs">61.3% of qualified sessions</div></div></div><div className="grid-2 mb-5"><section className="panel chart-box"><div className="section-title">Audience growth</div><div className="subtle text-xs mt-1 mb-4">Known contacts and qualified visitors</div><SparkChart values={[42, 45, 43, 51, 55, 53, 60, 64, 62, 70, 73, 78, 82]} color="hsl(36 94% 56%)" /><div className="flex justify-between text-[10px] subtle font-mono"><span>JAN</span><span>FEB</span><span>MAR</span></div></section><section className="panel p-5"><div className="section-title mb-5">Audience composition</div>{[['North America', 47], ['UK & Ireland', 24], ['DACH', 18], ['Rest of world', 11]].map(([name, value]) => <div key={name as string} className="flex items-center gap-3 mb-4"><div className="w-20 text-xs">{name}</div><div className="flex-1 progress-track"><div className="progress-fill" style={{ width: `${value}%`, background: 'hsl(var(--accent))' }} /></div><span className="w-8 text-right font-mono text-xs">{value}%</span></div>)}</section></div><section className="panel table-wrap"><div className="p-5 pb-1 section-title">Segments</div><table><thead><tr><th>Segment</th><th>Profile</th><th>Interests</th><th>Behavior</th><th>Size</th><th>Change</th></tr></thead><tbody>{segments.map(s => <tr key={s.id}><td className="font-semibold">{s.name}</td><td><div>{s.age}</div><div className="text-[11px] subtle">{s.location} · {s.device}</div></td><td><div className="flex gap-1">{s.interests.map(i => <span className="badge bg-[hsl(var(--muted))]" key={i}>{i}</span>)}</div></td><td>{s.behavior}</td><td className="font-mono">{s.size.toLocaleString()}</td><td className={s.change > 0 ? 'stat-change' : 'text-[hsl(var(--destructive))]'}>{s.change > 0 ? '+' : ''}{s.change}%</td></tr>)}</tbody></table></section></div>;
}

function Content() {
  const [platform, setPlatform] = useState('All'); const [query, setQuery] = useState('');
  const filtered = postsSeed.filter(p => (platform === 'All' || p.platform === platform) && p.title.toLowerCase().includes(query.toLowerCase()));
  return <div className="mp-content"><PageHeader eyebrow="Workspace / content" title="Content performance" copy="A living read on what earns attention — and what earns action." actions={<button className="btn btn-primary" onClick={() => alert('Content brief started')} data-testid="button-new-content"><Plus size={15} /> New content brief</button>} /><div className="stat-grid mb-5"><StatCard label="Total reach" value="246.8k" change="+16.1%" icon={Users} /><StatCard label="Avg. engagement" value="5.92%" change="+1.2%" icon={Heart} accent /><StatCard label="Total clicks" value="9,816" change="+21.7%" icon={MousePointerClick} /><StatCard label="Top platform" value="LinkedIn" change="4.84% avg. CTR" icon={TrendingUp} /></div><div className="panel p-3 mb-4 flex flex-wrap gap-2 items-center"><div className="relative flex-1 min-w-[220px]"><Search size={15} className="absolute left-3 top-3 subtle" /><input className="search-input pl-9" value={query} onChange={e => setQuery(e.target.value)} placeholder="Search content..." data-testid="input-search-content" /></div>{['All', 'LinkedIn', 'Instagram', 'YouTube', 'Email'].map(x => <button key={x} className={`btn ${platform === x ? 'btn-primary' : 'btn-soft'}`} onClick={() => setPlatform(x)} data-testid={`button-platform-${x.toLowerCase()}`}>{x}</button>)}</div><section className="panel table-wrap"><table><thead><tr><th>Content</th><th>Platform</th><th>Reach</th><th>Engagement</th><th>Clicks</th><th>Signal</th><th></th></tr></thead><tbody>{filtered.map(p => <tr key={p.id}><td className="font-semibold max-w-[310px]">{p.title}<div className="text-[11px] subtle mt-1">{p.likes.toLocaleString()} likes · {p.comments} comments · {p.shares} shares</div></td><td><span className="badge bg-[hsl(var(--muted))]">{p.platform}</span></td><td className="font-mono">{compact(p.reach)}</td><td className="font-mono">{p.engagementRate.toFixed(2)}%</td><td className="font-mono">{p.clicks.toLocaleString()}</td><td>{p.topPerformer ? <span className="badge badge-active"><Sparkles size={11} /> Top performer</span> : <span className="subtle text-xs">Steady</span>}</td><td><button className="btn btn-ghost p-2" onClick={() => alert(`Opening ${p.title}`)} aria-label="View content" data-testid={`button-view-content-${p.id}`}><MoreHorizontal size={16} /></button></td></tr>)}</tbody></table>{!filtered.length && <EmptyState title="No content found" copy="Try another platform or search phrase." />}</section></div>;
}

function SEO() {
  return <div className="mp-content"><PageHeader eyebrow="Workspace / seo intelligence" title="SEO intelligence" copy="Turn search visibility into a focused editorial backlog." actions={<button className="btn btn-soft" onClick={() => alert('Keyword CSV prepared')} data-testid="button-export-keywords"><Download size={15} /> Export keywords</button>} /><div className="stat-grid mb-5"><StatCard label="Tracked keywords" value="128" change="+14 this month" icon={ListFilter} /><StatCard label="Avg. position" value="11.6" change="↑ 2.4 positions" icon={TrendingUp} accent /><StatCard label="Organic clicks" value="18.4k" change="+22.8%" icon={MousePointerClick} /><StatCard label="Visibility" value="64.2%" change="+6.8%" icon={Globe2} /></div><div className="grid-2 mb-5"><section className="panel chart-box"><div className="section-title">Search visibility</div><div className="subtle text-xs mt-1">12-week trend across tracked topics</div><SparkChart values={[38, 41, 40, 46, 44, 51, 54, 52, 59, 63, 61, 67, 72]} color="hsl(215 68% 55%)" /></section><section className="panel p-5"><div className="section-title mb-4">Technical health</div><div className="flex items-end gap-3 mb-4"><div className="text-4xl font-semibold tracking-tight">92</div><div className="subtle text-xs pb-1">out of 100</div></div><div className="progress-track h-2 mb-5"><div className="progress-fill" style={{ width: '92%', background: 'hsl(215 68% 55%)' }} /></div>{[['Indexation', 'Healthy'], ['Core web vitals', 'Healthy'], ['Metadata coverage', 'Needs review']].map(([name, state]) => <div key={name} className="flex justify-between py-2 border-b border-[hsl(var(--border))] last:border-0 text-xs"><span>{name}</span><span className={state === 'Healthy' ? 'text-[hsl(var(--primary))]' : 'text-[hsl(var(--accent-foreground))]'}>{state}</span></div>)}</section></div><section className="panel table-wrap"><div className="p-5 pb-1 flex justify-between items-center"><div><div className="section-title">Keyword watchlist</div><div className="subtle text-xs mt-1">Prioritized by opportunity and momentum</div></div><button className="btn btn-soft" onClick={() => alert('Keyword added to watchlist')} data-testid="button-add-keyword"><Plus size={14} /> Add keyword</button></div><table><thead><tr><th>Keyword</th><th>Position</th><th>Search volume</th><th>Momentum</th><th>Opportunity</th></tr></thead><tbody>{keywordsSeed.map(k => <tr key={k.keyword}><td className="font-semibold">{k.keyword}</td><td className="font-mono">#{k.position}</td><td className="font-mono">{k.searchVolume.toLocaleString()}</td><td><span className={k.trend === 'up' ? 'stat-change flex items-center gap-1' : k.trend === 'down' ? 'text-[hsl(var(--destructive))] flex items-center gap-1' : 'subtle flex items-center gap-1'}>{k.trend === 'up' ? <ArrowUpRight size={13} /> : k.trend === 'down' ? <ArrowDownRight size={13} /> : <span>—</span>}{k.trend}</span></td><td><div className="w-28 progress-track"><div className="progress-fill" style={{ width: `${Math.max(24, 100 - k.position * 2.2)}%`, background: 'hsl(215 68% 55%)' }} /></div></td></tr>)}</tbody></table></section></div>;
}

function CalendarPage({ campaigns }: { campaigns: Campaign[] }) {
  const [month, setMonth] = useState(new Date(2025, 2, 1)); const first = new Date(month.getFullYear(), month.getMonth(), 1).getDay(); const days = new Date(month.getFullYear(), month.getMonth() + 1, 0).getDate(); const cells = Array.from({ length: 42 }, (_, i) => i - first + 1);
  return <div className="mp-content"><PageHeader eyebrow="Plan & learn / calendar" title="Campaign calendar" copy="A shared rhythm for launches, content, and the moments in between." actions={<button className="btn btn-primary" onClick={() => alert('Event composer opened')} data-testid="button-add-calendar-event"><Plus size={15} /> Add event</button>} /><section className="panel p-5"><div className="section-head"><div className="flex items-center gap-2"><button className="btn btn-soft p-2" onClick={() => setMonth(new Date(month.getFullYear(), month.getMonth() - 1, 1))} data-testid="button-previous-month">‹</button><div className="section-title min-w-[150px] text-center">{month.toLocaleDateString('en-US', { month: 'long', year: 'numeric' })}</div><button className="btn btn-soft p-2" onClick={() => setMonth(new Date(month.getFullYear(), month.getMonth() + 1, 1))} data-testid="button-next-month">›</button></div><div className="flex gap-3 text-xs subtle"><span><i className="inline-block w-2 h-2 rounded-full bg-[hsl(var(--primary))] mr-1" />Campaigns</span><span><i className="inline-block w-2 h-2 rounded-full bg-[hsl(var(--accent))] mr-1" />Content</span></div></div><div className="calendar-grid">{['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'].map(d => <div key={d} className="p-2 border-r border-b border-[hsl(var(--border))] text-[10px] font-mono uppercase subtle">{d}</div>)}{cells.map(n => <div key={n} className={`calendar-cell ${n < 1 || n > days ? 'muted-day' : ''}`}><div className="text-xs font-mono">{n < 1 ? new Date(month.getFullYear(), month.getMonth(), n).getDate() : n > days ? n - days : n}</div>{campaigns.filter(c => { const day = Number(c.startDate.slice(-2)); return n === day && c.startDate.slice(0, 7) === `${month.getFullYear()}-${String(month.getMonth() + 1).padStart(2, '0')}`; }).map(c => <Link href={`/campaigns/${c.id}`} key={c.id} className="calendar-event" data-testid={`event-${c.id}`}>{c.name}</Link>)}{n === 18 && month.getMonth() === 2 && <div className="calendar-event" style={{ background: 'hsl(var(--accent) / .2)', borderColor: 'hsl(var(--accent))' }}>Editorial review</div>}</div>)}</div></section></div>;
}

function Insights() {
  return <div className="mp-content"><PageHeader eyebrow="Plan & learn / insights" title="Marketing insights" copy="A short list of decisions the data is asking you to make." actions={<button className="btn btn-soft" onClick={() => alert('Insights refreshed')} data-testid="button-refresh-insights"><Activity size={15} /> Refresh signals</button>} /><div className="grid-2"><div className="space-y-3">{insights.map((i, idx) => <article className="panel p-5 panel-hover reveal" style={{ animationDelay: `${idx * .06}s` }} key={i.id}><div className="flex justify-between gap-4"><div className="flex gap-3"><div className={`w-9 h-9 rounded-lg grid place-items-center shrink-0 ${i.type === 'Opportunity' ? 'bg-blue-500/10 text-blue-500' : i.type === 'Watch' ? 'bg-[hsl(var(--accent)/.2)] text-[hsl(var(--accent-foreground))]' : 'bg-[hsl(var(--primary)/.12)] text-[hsl(var(--primary))]'}`}>{i.type === 'Opportunity' ? <Zap size={17} /> : i.type === 'Watch' ? <Clock3 size={17} /> : <Check size={17} />}</div><div><div className="flex items-center gap-2"><span className="eyebrow">{i.type}</span><span className="text-[10px] subtle">· 2h ago</span></div><h2 className="font-semibold mt-1">{i.title}</h2><p className="subtle text-sm leading-relaxed mt-2">{i.copy}</p></div></div><div className="text-right shrink-0"><div className="font-semibold">{i.metric}</div><button className="text-xs text-[hsl(var(--primary))] font-semibold mt-3" onClick={() => alert(`${i.action} opened`)} data-testid={`button-insight-action-${i.id}`}>{i.action} <ChevronRight size={12} className="inline" /></button></div></div></article>)}</div><aside className="panel p-5 h-fit sticky top-24"><div className="section-title">Signal methodology</div><p className="subtle text-sm leading-relaxed mt-2">MarketPulse looks for meaningful movement across delivery, audience fit, creative response, and conversion velocity. We only surface a signal when there is a clear next move.</p><div className="border-t border-[hsl(var(--border))] my-5" /><div className="eyebrow mb-3">This week’s pulse</div>{[['Signals surfaced', '12'], ['Decisions made', '07'], ['Campaigns monitored', '06']].map(([a, b]) => <div className="flex justify-between py-2 text-sm" key={a}><span className="subtle">{a}</span><span className="font-semibold">{b}</span></div>)}</aside></div></div>;
}

function Reports({ campaigns }: { campaigns: Campaign[] }) {
  return <div className="mp-content"><div className="report-print"><PageHeader eyebrow="Plan & learn / reports" title="Executive report" copy="A clean, printable readout for the next marketing review." actions={<><button className="btn btn-soft no-print" onClick={() => window.print()} data-testid="button-print-report"><Printer size={15} /> Print report</button><button className="btn btn-primary no-print" onClick={() => alert('PDF export is ready in your browser print dialog')} data-testid="button-download-report"><Download size={15} /> Download</button></>} /><div className="panel p-6 mb-5"><div className="flex flex-wrap justify-between gap-5"><div><div className="eyebrow">MarketPulse / weekly readout</div><h2 className="text-2xl font-semibold mt-2" style={{ fontFamily: 'var(--font-display)' }}>The signal is compounding.</h2><p className="subtle text-sm mt-2">Reporting period · February 17 — March 18, 2025</p></div><div className="text-right"><Logo /><div className="eyebrow mt-2">Prepared for Growth team</div></div></div></div><div className="stat-grid mb-5"><StatCard label="Portfolio reach" value="692k" change="+18.6%" icon={Users} /><StatCard label="Qualified conversions" value="1,494" change="+14.2%" icon={TrendingUp} accent /><StatCard label="Blended ROAS" value="3.86×" change="+0.34×" icon={CircleGauge} /><StatCard label="Portfolio health" value="84 / 100" change="+6 pts" icon={ShieldCheck} /></div><div className="grid-2 mb-5"><section className="panel p-5"><div className="section-title">What moved</div><div className="space-y-4 mt-5">{['LinkedIn became the most efficient reach channel.', 'Retention campaign closed at 5.28× ROAS.', 'North Star Accounts needs a creative reset.'].map((x, i) => <div className="flex gap-3" key={x}><div className="w-6 h-6 rounded-full bg-[hsl(var(--primary)/.12)] text-[hsl(var(--primary))] grid place-items-center text-xs font-mono">{String(i + 1).padStart(2, '0')}</div><div className="text-sm">{x}</div></div>)}</div></section><section className="panel p-5"><div className="section-title">Portfolio by status</div><div className="space-y-4 mt-5">{(['Active', 'Planned', 'Completed', 'Paused'] as Status[]).map(s => <div className="flex items-center gap-3" key={s}><div className="w-20 text-xs"><StatusBadge status={s} /></div><div className="flex-1 progress-track"><div className="progress-fill" style={{ width: `${s === 'Active' ? 50 : s === 'Completed' ? 33 : 17}%` }} /></div><span className="font-mono text-xs">{campaigns.filter(c => c.status === s).length}</span></div>)}</div></section></div><section className="panel table-wrap"><div className="p-5 pb-1 section-title">Campaign scorecard</div><table><thead><tr><th>Campaign</th><th>Status</th><th>Health</th><th>Conversions</th><th>ROAS</th></tr></thead><tbody>{campaigns.map(c => <tr key={c.id}><td className="font-semibold">{c.name}</td><td><StatusBadge status={c.status} /></td><td className="font-mono">{c.healthScore}</td><td className="font-mono">{c.metrics.conversions.toLocaleString()}</td><td className="font-mono">{c.metrics.roas.toFixed(2)}×</td></tr>)}</tbody></table></section><div className="subtle text-xs mt-5 text-center">Generated by MarketPulse · Decision-ready by design</div></div></div>;
}

function Login({ onLogin }: { onLogin: () => void }) {
  const [email, setEmail] = useState('jordan@northstar.co'); const [password, setPassword] = useState('marketpulse'); const [error, setError] = useState('');
  const submit = (e: React.FormEvent) => { e.preventDefault(); if (!email.includes('@') || password.length < 4) { setError('Enter a valid email and password to continue.'); return; } storage.set('mp-auth', true); onLogin(); };
  return <div className="login-layout"><aside className="login-aside"><Logo dark /><div className="login-copy max-w-md relative z-10"><div className="eyebrow text-[hsl(var(--primary))]">The marketing command center</div><h1 className="text-5xl font-semibold tracking-[-.07em] leading-[.98] mt-4">Make the next<br /><span className="text-[hsl(var(--primary))]">move obvious.</span></h1><p className="text-slate-400 leading-relaxed mt-6 max-w-sm">MarketPulse turns scattered channel metrics into a calm, confident operating rhythm.</p><div className="flex gap-7 mt-10"><div><div className="text-2xl font-semibold text-white">3.86×</div><div className="eyebrow mt-1">blended ROAS</div></div><div><div className="text-2xl font-semibold text-white">84</div><div className="eyebrow mt-1">health score</div></div></div></div><div className="relative z-10 text-xs text-slate-500">Trusted by teams who prefer signal over noise.</div></aside><main className="login-main"><form className="login-form reveal" onSubmit={submit}><div className="eyebrow">Welcome back</div><h2 className="text-3xl font-semibold tracking-[-.05em] mt-2">Sign in to your workspace</h2><p className="subtle text-sm mt-2 mb-8">Your team’s clearest decisions are waiting.</p><label className="form-label">Work email</label><input className="form-input mb-4" type="email" value={email} onChange={e => setEmail(e.target.value)} data-testid="input-login-email" /><label className="form-label">Password</label><input className="form-input" type="password" value={password} onChange={e => setPassword(e.target.value)} data-testid="input-login-password" />{error && <div className="form-error mt-2">{error}</div>}<button className="btn btn-primary w-full mt-6" type="submit" data-testid="button-login">Enter MarketPulse <ChevronRight size={15} /></button><button type="button" className="btn btn-ghost w-full mt-2" onClick={() => { setEmail('jordan@northstar.co'); setPassword('marketpulse'); setError(''); }} data-testid="button-demo-login">Use demo workspace</button><div className="flex items-center gap-2 mt-8 text-xs subtle"><ShieldCheck size={14} className="text-[hsl(var(--primary))]" /> Demo data is stored locally in this browser.</div></form></main></div>;
}

function NotFound() { return <div className="min-h-[100dvh] grid place-items-center p-6"><div className="text-center"><div className="eyebrow">404 / signal lost</div><h1 className="page-title mt-2">This page is off the map.</h1><Link className="btn btn-primary mt-5" href="/dashboard" data-testid="link-not-found-home">Back to command center</Link></div></div>; }

function AppRouter() {
  const [location, setLocation] = useLocation(); const [auth, setAuth] = useState(() => storage.get('mp-auth', false)); const [dark, setDark] = useState(() => storage.get('mp-theme', false)); const [campaigns, setCampaigns] = usePersistent('mp-campaigns', campaignsSeed); const [segments] = usePersistent('mp-segments', segmentsSeed); const [toast, setToast] = useState('');
  useEffect(() => { document.documentElement.classList.toggle('dark', dark); storage.set('mp-theme', dark); }, [dark]);
  useEffect(() => { if (toast) { const t = window.setTimeout(() => setToast(''), 2600); return () => window.clearTimeout(t); } return undefined; }, [toast]);
  const notify = (s: string) => setToast(s);
  if (!auth && location !== '/login') return <Login onLogin={() => { setAuth(true); setLocation('/dashboard'); }} />;
  if (auth && location === '/login') { setLocation('/dashboard'); return null; }
  if (location === '/') { setLocation(auth ? '/dashboard' : '/login'); return null; }
  const page = <Switch><Route path="/login"><Login onLogin={() => { setAuth(true); setLocation('/dashboard'); }} /></Route><Route path="/dashboard"><Dashboard campaigns={campaigns} /></Route><Route path="/campaigns/new"><CampaignForm onCancel={() => setLocation('/campaigns')} onSave={c => { setCampaigns([...campaigns, c]); setLocation(`/campaigns/${c.id}`); }} notify={notify} /></Route><Route path="/campaigns/:id"><CampaignDetail campaigns={campaigns} setCampaigns={setCampaigns} notify={notify} /></Route><Route path="/campaigns"><Campaigns campaigns={campaigns} setCampaigns={setCampaigns} notify={notify} /></Route><Route path="/analytics"><Analytics campaigns={campaigns} /></Route><Route path="/audience"><Audience segments={segments} /></Route><Route path="/content"><Content /></Route><Route path="/seo"><SEO /></Route><Route path="/calendar"><CalendarPage campaigns={campaigns} /></Route><Route path="/insights"><Insights /></Route><Route path="/reports"><Reports campaigns={campaigns} /></Route><Route component={NotFound} /></Switch>;
  return <Shell onTheme={() => setDark(v => !v)} onLogout={() => { storage.set('mp-auth', false); setAuth(false); setLocation('/login'); }}>{page}{toast && <div className="toast" role="status" data-testid="status-toast"><Check size={15} className="inline mr-2 text-[hsl(var(--primary))]" />{toast}</div>}</Shell>;
}

function App() { return <QueryClientProvider client={queryClient}><TooltipProvider><WouterRouter base={import.meta.env.BASE_URL.replace(/\/$/, '')}><ErrorBoundary resetKey={location.pathname}><AppRouter /></ErrorBoundary></WouterRouter><Toaster /></TooltipProvider></QueryClientProvider>; }

export default App;